long long sumv=0, sumc=0;
for(int i=0;i<n;i++){
  __int128 d=(__int128)A[i] - (__int128)Y*B[i];
  if(d>0){ sumv += (long long)d; sumc += B[i]; }
}
if(sumc > X){
  long long cand = (long long)((__int128)X*Y + sumv);
  if(cand>best) best=cand;
}
return best;

